package org.brightstats.stats;

import java.util.*;
import org.apache.commons.math3.distribution.TDistribution;

/** Published paired-loss CVPAT arithmetic and explicit original-unit predictive error diagnostics. */
public final class PredictionInference {
    private PredictionInference(){}
    public enum Benchmark { INDICATOR_AVERAGE, LINEAR_MODEL }
    public record ErrorMetric(int target,int forecasts,int zeroActual,int nearZeroActual,int percentageObservations,
                              double mape,double smape,double medianAbsoluteError,double percentile95AbsoluteError,double relativeMae){}
    public record Comparison(String scope,int construct,int target,Benchmark benchmark,int observations,
                             double plsLoss,double benchmarkLoss,double meanDifference,double standardDeviation,double standardError,
                             double statistic,int degreesOfFreedom,double lower,double upper,double upperOneSided,
                             double pOneSided,double pHolm,String status){}
    public record Result(double confidence,String method,List<ErrorMetric> metrics,List<Comparison> comparisons,List<String> warnings){public Result{metrics=List.copyOf(metrics);comparisons=List.copyOf(comparisons);warnings=List.copyOf(warnings);}}
    private static final class Average {int count;double pls,mean,linear,actual;void add(Prediction.Row row){if(count>0&&Double.compare(actual,row.actual())!=0)throw new IllegalArgumentException("Actual outcome differs across repeats for the same observation.");actual=row.actual();count++;double a=square(row.actual()-row.pls()),b=square(row.actual()-row.mean()),c=square(row.actual()-row.linear());pls+=(a-pls)/count;mean+=(b-mean)/count;linear+=(c-linear)/count;}}
    private static double square(double value){double result=value*value;if(!Double.isFinite(result))throw new IllegalArgumentException("Predictive squared loss exceeded the finite numeric range.");return result;}
    private static double quantile(double[] sorted,double probability){if(sorted.length==0)return Double.NaN;double index=probability*(sorted.length-1);int lower=(int)Math.floor(index),upper=(int)Math.ceil(index);return sorted[lower]+(index-lower)*(sorted[upper]-sorted[lower]);}
    private static ErrorMetric metric(List<Prediction.Row> rows,int target){List<Prediction.Row> selected=rows.stream().filter(row->row.target()==target&&Double.isFinite(row.actual())).toList();if(selected.isEmpty())return new ErrorMetric(target,0,0,0,0,Double.NaN,Double.NaN,Double.NaN,Double.NaN,Double.NaN);double scale=selected.stream().mapToDouble(row->Math.abs(row.actual())).max().orElse(0),mape=0,smape=0,mae=0,benchmarkMae=0;int zero=0,near=0,percentage=0;double[] absolute=new double[selected.size()];for(int i=0;i<selected.size();i++){var row=selected.get(i);double error=Math.abs(row.actual()-row.pls()),meanError=Math.abs(row.actual()-row.mean());if(!Double.isFinite(error)||!Double.isFinite(meanError))throw new IllegalArgumentException("Predictive absolute loss exceeded the finite numeric range.");absolute[i]=error;mae+=(error-mae)/(i+1);benchmarkMae+=(meanError-benchmarkMae)/(i+1);if(row.actual()==0)zero++;else{if(Math.abs(row.actual())<=scale*1e-8)near++;double relative=100*(error/Math.abs(row.actual()));if(Double.isFinite(relative)){percentage++;mape+=(relative-mape)/percentage;}}double largest=Math.max(Math.abs(row.actual()),Math.abs(row.pls())),symmetric=largest==0?0:200*Math.abs(row.actual()/largest-row.pls()/largest)/(Math.abs(row.actual()/largest)+Math.abs(row.pls()/largest));smape+=(symmetric-smape)/(i+1);}Arrays.sort(absolute);return new ErrorMetric(target,selected.size(),zero,near,percentage,percentage==0?Double.NaN:mape,smape,quantile(absolute,.5),quantile(absolute,.95),benchmarkMae==0?Double.NaN:mae/benchmarkMae);}
    public static Comparison paired(String scope,int construct,int target,Benchmark benchmark,double[] pls,double[] other,double confidence){var result=PairedLossTest.evaluate(pls,other,confidence);return new Comparison(scope,construct,target,benchmark,result.observations(),result.firstLoss(),result.secondLoss(),result.difference(),result.standardDeviation(),result.standardError(),result.statistic(),result.degreesOfFreedom(),result.lower(),result.upper(),result.upperOneSided(),result.pFirstBetter(),Double.NaN,result.status());}

    public static Result evaluate(Prediction.Result prediction,double confidence){Objects.requireNonNull(prediction);if(!Double.isFinite(confidence)||confidence<=0||confidence>=1)throw new IllegalArgumentException("Choose a confidence level between zero and one.");List<ErrorMetric> metrics=new ArrayList<>();List<String> warnings=new ArrayList<>();int targets=prediction.targets().size();Set<String> seen=new HashSet<>();Map<Integer,Map<Integer,Average>> byCase=new TreeMap<>();int[][] assignments=prediction.assignments();if(assignments.length!=prediction.options().repeats())throw new IllegalArgumentException("Forecast repeat assignments differ from options.");for(var row:prediction.predictions()){Matrices.interrupted();if(row.target()<0||row.target()>=targets||row.repeat()<1||row.repeat()>prediction.options().repeats()||row.row()<1||row.row()>assignments[row.repeat()-1].length||!seen.add(row.repeat()+":"+row.row()+":"+row.target()))throw new IllegalArgumentException("Invalid or duplicate held-out forecast identity.");if(row.fold()<1||row.fold()!=assignments[row.repeat()-1][row.row()-1])throw new IllegalArgumentException("Forecast does not match its held-out fold assignment.");if(!Double.isFinite(row.pls())||!Double.isFinite(row.mean())||!Double.isFinite(row.linear()))throw new IllegalArgumentException("Held-out forecasts must be finite.");if(Double.isInfinite(row.actual()))throw new IllegalArgumentException("Held-out actual values must be finite or missing.");if(Double.isFinite(row.actual()))byCase.computeIfAbsent(row.row(),unused->new HashMap<>()).computeIfAbsent(row.target(),unused->new Average()).add(row);}
        for(int target=0;target<targets;target++)metrics.add(metric(prediction.predictions(),target));List<Comparison> comparisons=new ArrayList<>();if(prediction.options().scheme()==Prediction.Scheme.K_FOLD){List<int[]> scopes=new ArrayList<>();List<String> labels=new ArrayList<>();List<Integer> constructs=new ArrayList<>(),indicator=new ArrayList<>();scopes.add(java.util.stream.IntStream.range(0,targets).toArray());labels.add("OVERALL");constructs.add(-1);indicator.add(-1);Set<Integer> unique=new TreeSet<>();for(var target:prediction.targets())unique.add(target.construct());for(int construct:unique){scopes.add(java.util.stream.IntStream.range(0,targets).filter(index->prediction.targets().get(index).construct()==construct).toArray());labels.add("CONSTRUCT");constructs.add(construct);indicator.add(-1);}for(int target=0;target<targets;target++){scopes.add(new int[]{target});labels.add("INDICATOR");constructs.add(prediction.targets().get(target).construct());indicator.add(target);}for(int scope=0;scope<scopes.size();scope++){Matrices.interrupted();int[] selected=scopes.get(scope);if(selected.length==0)continue;List<double[]> pairs=new ArrayList<>();for(var values:byCase.values()){boolean complete=true;double a=0,b=0,c=0;for(int index=0;index<selected.length;index++){Average value=values.get(selected[index]);if(value==null||value.count!=prediction.options().repeats()){complete=false;break;}a+=(value.pls-a)/(index+1);b+=(value.mean-b)/(index+1);c+=(value.linear-c)/(index+1);}if(complete)pairs.add(new double[]{a,b,c});}double[] a=pairs.stream().mapToDouble(pair->pair[0]).toArray();for(var benchmark:Benchmark.values()){int column=benchmark==Benchmark.INDICATOR_AVERAGE?1:2;double[] b=pairs.stream().mapToDouble(pair->pair[column]).toArray();comparisons.add(paired(labels.get(scope),constructs.get(scope),indicator.get(scope),benchmark,a,b,confidence));}}Map<String,List<Integer>> equivalent=new LinkedHashMap<>();for(int index=0;index<comparisons.size();index++)equivalent.computeIfAbsent(Arrays.toString(scopes.get(index/2))+comparisons.get(index).benchmark(),unused->new ArrayList<>()).add(index);List<Integer> order=equivalent.values().stream().map(indices->indices.getFirst()).filter(index->Double.isFinite(comparisons.get(index).pOneSided())).sorted(Comparator.comparingDouble(index->comparisons.get(index).pOneSided())).toList();double previous=0;for(int rank=0;rank<order.size();rank++){int index=order.get(rank);Comparison old=comparisons.get(index);double adjusted=Math.min(1,Math.max(previous,(order.size()-rank)*old.pOneSided()));previous=adjusted;for(int equivalentIndex:equivalent.get(Arrays.toString(scopes.get(index/2))+old.benchmark()))comparisons.set(equivalentIndex,new Comparison(old.scope(),old.construct(),old.target(),old.benchmark(),old.observations(),old.plsLoss(),old.benchmarkLoss(),old.meanDifference(),old.standardDeviation(),old.standardError(),old.statistic(),old.degreesOfFreedom(),old.lower(),old.upper(),old.upperOneSided(),old.pOneSided(),adjusted,old.status()));}}else warnings.add("CVPAT is not calculated for repeated holdout. Use complete repeated k-fold validation for the paired-case comparison.");
        warnings.add("CVPAT uses published paired-loss t arithmetic on original-unit squared prediction errors. Repeated forecasts are averaged within each observation before inference; repeats are not treated as independent sample rows. Only cases observed for every target/repeat in a reported scope enter that comparison.");warnings.add("A negative loss difference favors PLS. Raw one-sided p-values and Holm-adjusted p-values across distinct valid scopes/benchmarks (identical indicator sets count once) are separate; two-sided confidence intervals and a one-sided upper bound are also separate. Zero empirical loss variance suppresses inference rather than claiming certainty.");warnings.add("Overall/construct losses average squared errors across indicators in their original units, so units affect their weighting. These are IID cross-sectional comparisons with overlapping training folds; they do not establish time-series/grouped predictive validity, global model superiority or native SmartPLS numerical equivalence.");if(metrics.stream().anyMatch(metric->metric.zeroActual()>0||metric.nearZeroActual()>0||metric.percentageObservations()<metric.forecasts()))warnings.add("MAPE excludes exactly zero actual values and nonfinite percentage ratios; usable counts are explicit. Near-zero outcomes can dominate MAPE. SMAPE defines an actual/predicted zero pair as zero; examine MAE, RMSE and robust absolute-error quantiles alongside percentages.");return new Result(confidence,"Paired-case squared-loss CVPAT with Student t reference; repeat averaging and family-wise Holm adjustment",metrics,comparisons,warnings);
    }
}
